pub const Node = struct {
    value: i32,
    next: ?*Node,
};

pub fn reverseLinkedList(head: ?*Node) ?*Node {
    var prev: ?*Node = null;
    var current: ?*Node = head;

    while (current) |node| {
        const next_node = node.next;
        node.next = prev;
        prev = node;
        current = next_node;
    }

    return prev;
}
